const b = $('Webhook').first().json.body || {};
const hdr = $('Webhook').first().json.headers || {};
const raw = (b.token || hdr.authorization || '').replace(/^Bearer\s+/i, '');
let userId = '', role = '';
try {
  const response = await fetch('{{ $env.SUPABASE_URL || "https://VOTRE-PROJET-SUPABASE.supabase.co" }}/auth/v1/user', {
    headers: { Authorization: `Bearer ${raw}`, apikey: '{{ $env.SUPABASE_ANON_KEY || "VOTRE_SUPABASE_ANON_KEY" }}' }
  });
  if (!response.ok) throw new Error('Token invalid');
  const user = await response.json();
  userId = user.id || '';
  role = (user.user_metadata && user.user_metadata.role) || (user.app_metadata && user.app_metadata.role) || '';
} catch (e) {}
const valid = !!userId && String(role).toLowerCase() === 'admin';
return [{ json: { userId, role, token: raw, sessionId: b.sessionid || ('admin-' + userId), userMessage: b.message || '', valid: valid ? 'true' : 'false' } }];

const auth = $('Code - Auth JWT').first().json;

let historyText = '';
try {
  const mem = $('Get Long-Term Memory').first().json;
  const rows = Array.isArray(mem) ? mem : (mem?.conversation_data ? mem : []);
  historyText = (Array.isArray(rows) ? rows : [rows]).map(r => {
    const cd = r.conversation_data || r;
    return `Admin: ${cd.user || ''}\nKayvibot: ${cd.assistant || ''}`;
  }).join('\n');
} catch {}

let gbrainText = '';
try { gbrainText = JSON.stringify($('gbrain Recall').first().json); } catch {}

let adminData = {};
let dailyBriefing = '';
let healthScores = '';
let occupancy = '';
try {
  const res = $('Fetch Admin Context').first().json;
  adminData = res.context || {};
  const analytics = res.analytics || {};
  dailyBriefing = JSON.stringify(analytics.daily_briefing || '');
  healthScores = JSON.stringify(analytics.health_score_by_villa || {});
  occupancy = JSON.stringify(analytics.occupancy_by_villa || {});
} catch {}

const systemMessage = `Tu es le copilote admin de Kayvila. Tu supervises TOUTES les villas et tous les propriétaires.

HISTORIQUE :
${historyText || 'Aucun historique'}

MÉMOIRE SÉMANTIQUE (gbrain — patterns et incidents passés) :
${gbrainText || 'Aucune'}

DONNÉES COMPLÈTES (villas, bookings, submissions, stats, OTA, users, finances) :
${JSON.stringify(adminData, null, 2)}

BRIEFING QUOTIDIEN (L1 — check-ins/outs, soumissions en attente) :
${dailyBriefing}
⚠️ OUVRE chaque conversation par ce briefing. Donne les chiffres d'abord.

SANTÉ VILLAS (L3/L4 — occupation + scores) :
${healthScores}
⚠️ Utilise ces scores pour comparer les villas entre elles. Identifie celle(s) à risque (score < 50).

OCCUPATION PAR VILLA :
${occupancy}
⚠️ Données réelles sur 30 jours glissants. Compare, classe, alerte sur les sous-performances.

MESSAGE FONDATEUR : ${auth.userMessage}
DATE : ${new Date().toLocaleDateString('fr-FR', { timeZone: 'America/Martinique' })}

SOURCE DE VÉRITÉ : les DONNÉES CI-DESSUS. Utilise UNIQUEMENT ce qui est fourni dans ce contexte. Tu n'as pas d'outils externes.

TON RÔLE :
- OUVRIR par le briefing quotidien + les alertes, avant toute question
- Donner une vue d'ensemble de la plateforme
- Détecter les problèmes (OTA, impayés, soumissions en attente)
- Alerter proactivement sur les anomalies
- Formuler des recommandations actionnables (L2)
- Ne JAMAIS modifier la base de données sans confirmation explicite

ACTIONS DISPONIBLES (émettre en JSON dans ta réponse) :
- SHOW_STATS : afficher les statistiques
- CREATE_TASK : { "action_data": { "task": { "villa_id": "...", "title": "...", "type": "...", "due_date": "..." } } }
- BLOCK_DATE : { "action_data": { "block": { "villa_id": "...", "start_date": "...", "end_date": "...", "reason": "..." } } }
- UPDATE_BOOKING : { "action_data": { "booking_id": "...", "status": "..." } }
- UPDATE_TASK_STATUS : { "action_data": { "task_id": "...", "status": "..." } }
- UPDATE_SUBMISSION_STATUS : { "action_data": { "submission_id": "...", "status": "..." } }
- COMPLETE_TASK : { "action_data": { "task_id": "..." } }

ACTIONS DESTRUCTIVES (BLOCK_DATE, UPDATE_BOOKING, UPDATE_SUBMISSION_STATUS) :
⚠️ RÈGLE STRICTE : émets l'action SANS le champ "confirm". Attends que l'utilisateur réponde « oui ». Puis ré-émet avec "action_data.confirm = true".
Exemple 1er message : { "action": "BLOCK_DATE", "action_data": { "block": { ... } } }
Exemple 2e message (après « oui ») : { "action": "BLOCK_DATE", "action_data": { "block": { ... }, "confirm": true } }

TON TON :
- Direct, data-driven, exécutif
- Toujours sourcer les chiffres
- Alerter sans alarmisme`;

return { json: { sessionId: auth.sessionId, userId: auth.userId, userMessage: auth.userMessage, systemMessage } };

const i = $input.first().json;
let t = i.output || i.text || "Désolé, je rencontre un souci technique.";
t = t.replace(/\*\*(.*?)\*\*/g, '$1').replace(/^[ \t]*#+[ \t]+/gm, '').replace(/^[ \t]*-+[ \t]+/gm, '• ').trim();
return [{ json: { response: t, sessionId: $('Code - Auth JWT').first().json.sessionId, userId: $('Code - Auth JWT').first().json.userId } }];

const msg = ($('Code - Auth JWT').first().json.userMessage || '').toLowerCase();
const out = ($('AI Agent DeepSeek').first().json.output || '').toLowerCase();
const blob = msg + ' ' + out;
const criticalKw = ['panne', 'impayé', 'impaye', 'litige', 'erreur', 'échec', 'echec', 'bloqué', 'bloque', 'down', 'critique', 'anomalie', 'conflit'];
const submKw = ['soumission', 'submission', 'à valider', 'a valider', 'en attente', 'nouvelle villa', 'validation'];
const isCritical = criticalKw.some(k => blob.includes(k));
const hasSubmission = submKw.some(k => blob.includes(k));
return [{ json: { isCritical: isCritical ? 'true' : 'false', hasSubmission: hasSubmission ? 'true' : 'false', message: $('Code - Auth JWT').first().json.userMessage, aiOutput: $('AI Agent DeepSeek').first().json.output || '' } }];
